/* ================= KanbanForge pure functions (top-level, testable) ================= */
function esc(s){
  return String(s==null?'':s).replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;').replace(/"/g,'&quot;');
}
function uid(){
  return 'k' + Date.now().toString(36) + Math.random().toString(36).slice(2,8);
}
var COL_COLORS = ['#5E6AD2','#F5A623','#10B981','#22D3EE','#A78BFA','#F472B6','#FB923C'];
function defaultBoard(){
  return { columns:[
    { id:'c1', title:'待办', color:COL_COLORS[0], cards:[
      { id:'k1', title:'双击卡片可以编辑', desc:'', priority:'mid', tags:['上手'] },
      { id:'k2', title:'拖拽卡片到其他列', desc:'', priority:'', tags:[] }
    ]},
    { id:'c2', title:'进行中', color:COL_COLORS[1], cards:[
      { id:'k3', title:'体验 KanbanForge', desc:'离线看板，数据存在浏览器本地。', priority:'high', tags:['本地优先'] }
    ]},
    { id:'c3', title:'已完成', color:COL_COLORS[2], cards:[] }
  ]};
}
function findColumn(board, colId){
  for (var i=0;i<board.columns.length;i++) if (board.columns[i].id===colId) return board.columns[i];
  return null;
}
function findCard(board, cardId){
  for (var i=0;i<board.columns.length;i++){
    var col=board.columns[i];
    for (var j=0;j<col.cards.length;j++) if (col.cards[j].id===cardId) return { col:col, card:col.cards[j], index:j };
  }
  return null;
}
function addColumn(board, title){
  var col={ id:uid(), title:title||'新列', color:COL_COLORS[board.columns.length%COL_COLORS.length], cards:[] };
  board.columns.push(col);
  return col;
}
function removeColumn(board, colId){
  var before=board.columns.length;
  board.columns=board.columns.filter(function(c){return c.id!==colId;});
  return board.columns.length<before;
}
function addCard(board, colId, title){
  var col=findColumn(board,colId);
  if(!col) return null;
  var card={ id:uid(), title:title||'新卡片', desc:'', priority:'', tags:[] };
  col.cards.push(card);
  return card;
}
function removeCard(board, cardId){
  var hit=findCard(board,cardId);
  if(!hit) return false;
  hit.col.cards.splice(hit.index,1);
  return true;
}
function moveCard(board, cardId, toColId, toIndex){
  var hit=findCard(board,cardId);
  var toCol=findColumn(board,toColId);
  if(!hit||!toCol) return false;
  hit.col.cards.splice(hit.index,1);
  var idx=(typeof toIndex==='number'&&toIndex>=0)?Math.min(toIndex,toCol.cards.length):toCol.cards.length;
  toCol.cards.splice(idx,0,hit.card);
  return true;
}
function parseTags(s){
  return String(s==null?'':s).split(/[,，]/).map(function(t){return t.trim();}).filter(Boolean);
}
function matchCard(card, query){
  var q=String(query==null?'':query).trim().toLowerCase();
  if(!q) return true;
  if(q.charAt(0)==='#'){
    var tq=q.slice(1);
    return (card.tags||[]).some(function(t){return t.toLowerCase().indexOf(tq)>=0;});
  }
  var hay=(card.title+' '+(card.desc||'')+' '+(card.tags||[]).join(' ')).toLowerCase();
  return hay.indexOf(q)>=0;
}
function boardStats(board){
  var cols=board.columns.length, cards=0, high=0, done=0;
  board.columns.forEach(function(c,i){
    cards+=c.cards.length;
    c.cards.forEach(function(k){ if(k.priority==='high') high++; });
    if(i===board.columns.length-1) done=c.cards.length;
  });
  return { columns:cols, cards:cards, high:high, lastColCards:done };
}
function toMarkdown(board){
  var out=['# 看板',''];
  board.columns.forEach(function(c){
    out.push('## '+c.title+' ('+c.cards.length+')');
    c.cards.forEach(function(k){
      var line='- [ ] '+k.title;
      if(k.priority) line+=' `'+({high:'高',mid:'中',low:'低'})[k.priority]+'`';
      if(k.tags&&k.tags.length) line+=' '+k.tags.map(function(t){return '#'+t;}).join(' ');
      out.push(line);
      if(k.desc) out.push('  - '+k.desc.replace(/\n/g,' '));
    });
    out.push('');
  });
  return out.join('\n').replace(/\n+$/,'\n');
}
function toJSON(board){
  return JSON.stringify({ app:'KanbanForge', version:1, board:board }, null, 2);
}
function fromJSON(text){
  var data=JSON.parse(text);
  var b=data&&data.board?data.board:data;
  if(!b||!Array.isArray(b.columns)) throw new Error('invalid board');
  b.columns.forEach(function(c){
    if(typeof c.id!=='string'||typeof c.title!=='string'||!Array.isArray(c.cards)) throw new Error('invalid column');
    if(!c.color) c.color=COL_COLORS[0];
    c.cards.forEach(function(k){
      if(typeof k.id!=='string'||typeof k.title!=='string') throw new Error('invalid card');
      if(!Array.isArray(k.tags)) k.tags=[];
      if(typeof k.desc!=='string') k.desc='';
      if(typeof k.priority!=='string') k.priority='';
    });
  });
  return b;
}
if (typeof module !== 'undefined' && module.exports) {
  module.exports = { esc:esc, uid:uid, defaultBoard:defaultBoard, findColumn:findColumn, findCard:findCard,
    addColumn:addColumn, removeColumn:removeColumn, addCard:addCard, removeCard:removeCard, moveCard:moveCard,
    parseTags:parseTags, matchCard:matchCard, boardStats:boardStats, toMarkdown:toMarkdown, toJSON:toJSON, fromJSON:fromJSON };
}
if (typeof window !== 'undefined') {
  window.KanbanForgePure = { esc:esc, uid:uid, defaultBoard:defaultBoard, findColumn:findColumn, findCard:findCard,
    addColumn:addColumn, removeColumn:removeColumn, addCard:addCard, removeCard:removeCard, moveCard:moveCard,
    parseTags:parseTags, matchCard:matchCard, boardStats:boardStats, toMarkdown:toMarkdown, toJSON:toJSON, fromJSON:fromJSON };
}
